UPDATE discovered_pipelines SET description = CASE codename
  WHEN 'SOVEREIGN-GENESIS' THEN 'Enforces governance policies autonomously, detects and repairs system failures without downtime, and sequences complex multi-step operations with zero human oversight. The system self-governs, self-heals, and self-orchestrates.'
